static double llm_cost_ring_all_gather_time(
    double local_shard_bytes, int ranks, int gpu_per_node,
    double scale_bw, double scale_latency, double switch_latency,
    double nic_bw, double nic_latency
) {
    if (ranks <= 1) return 0.0;
    const bool crosses_node = gpu_per_node > 0 && ranks > gpu_per_node;
    const double bandwidth = crosses_node && nic_bw > 0.0 ? nic_bw : scale_bw;
    const double hop_latency = crosses_node && nic_latency > 0.0 ? nic_latency
        : (switch_latency > 0.0 ? switch_latency : scale_latency);
    return llm_comm_transfer_time_ns(
        std::max(local_shard_bytes, 0.0) * (ranks - 1), bandwidth, hop_latency, ranks - 1);
}

